import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pOC,
    .param .u32 pKH,
    .param .u32 pKW,
    .param .u32 pOH,
    .param .u32 pOW,
    .param .u32 pSTRH,
    .param .u32 pSTRW,
    .param .u32 pPADH,
    .param .u32 pPADW
)
{
    .reg .pred %p<12>;
    .reg .u32 %r<96>;
    .reg .u64 %rd<48>;
    .reg .s32 %s<16>;
    .reg .f32 %f<12>;
    .shared .align 16 .b8 smemW[4096];
    .shared .align 4 .b8 smemBias[4];
    // Load pointers
    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [b_ptr];
    ld.param.u64 %rd3, [y_ptr];
    // Load scalars
    ld.param.u32 %r10, [pN];
    ld.param.u32 %r11, [pC];
    ld.param.u32 %r12, [pH];
    ld.param.u32 %r13, [pW];
    ld.param.u32 %r14, [pOC];
    ld.param.u32 %r15, [pKH];
    ld.param.u32 %r16, [pKW];
    ld.param.u32 %r17, [pOH];
    ld.param.u32 %r18, [pOW];
    ld.param.u32 %r19, [pSTRH];
    ld.param.u32 %r20, [pSTRW];
    ld.param.u32 %r21, [pPADH];
    ld.param.u32 %r22, [pPADW];
    // Thread/block info
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %ctaid.x;
    // Precompute for cooperative weight staging and block mapping
    // wcount = C*KH*KW
    mul.lo.u32 %r64, %r11, %r15;
    mul.lo.u32 %r64, %r64, %r16;
    // ohow = OH*OW
    mul.lo.u32 %r68, %r17, %r18;
    // segments per (n, oc): S = ceil(ohow / blockDim.x)
    add.u32 %r80, %r68, %r1;
    sub.u32 %r80, %r80, 1;
    div.u32 %r81, %r80, %r1;
    // pair_index = ctaid.x / S, seg = ctaid.x % S
    div.u32 %r82, %r2, %r81;
    rem.u32 %r83, %r2, %r81;
    // Decompose pair_index into (n, oc)
    div.u32 %r27, %r82, %r14;    // n
    rem.u32 %r28, %r82, %r14;    // oc
      // Cooperative load of weights for this (oc) into shared memory with vectorized global->shared copies
      // baseW = oc * wcount
      mul.lo.u32 %r74, %r28, %r64;
      mov.u64 %rd40, smemW;
      // Vectorized phase: process 4-float groups per thread with stride blockDim.x*4
      and.b32 %r66, %r64, 0xFFFFFFFC;    // vec_end = wcount & ~3
      shl.b32 %r72, %r0, 2;              // idx4 = tid * 4
      shl.b32 %r73, %r1, 2;              // step4 = blockDim.x * 4
  WLOAD_VEC_LOOP:
      setp.ge.u32 %p8, %r72, %r66;
      @%p8 bra WLOAD_VEC_DONE;
      add.u32 %r75, %r74, %r72;          // total_idx = baseW + idx4
      mul.wide.u32 %rd41, %r75, 4;
      add.u64 %rd42, %rd1, %rd41;        // gaddr
      mul.wide.u32 %rd43, %r72, 4;
      add.u64 %rd44, %rd40, %rd43;       // saddr
      // Prefer v4 when global index is 16B aligned, else v2 when 8B aligned, else scalar
      and.b32 %r77, %r75, 3;
      setp.eq.u32 %p10, %r77, 0;
      @%p10 bra WLOAD_V4;
      and.b32 %r77, %r75, 1;
      setp.eq.u32 %p11, %r77, 0;
      @%p11 bra WLOAD_V2;
      // Scalar 4x32b path
      ld.global.f32 %f1, [%rd42];
      st.shared.f32 [%rd44], %f1;
      add.u64 %rd42, %rd42, 4;
      add.u64 %rd44, %rd44, 4;
      ld.global.f32 %f1, [%rd42];
      st.shared.f32 [%rd44], %f1;
      add.u64 %rd42, %rd42, 4;
      add.u64 %rd44, %rd44, 4;
      ld.global.f32 %f1, [%rd42];
      st.shared.f32 [%rd44], %f1;
      add.u64 %rd42, %rd42, 4;
      add.u64 %rd44, %rd44, 4;
      ld.global.f32 %f1, [%rd42];
      st.shared.f32 [%rd44], %f1;
      bra WLOAD_STEP;
  WLOAD_V2:
      ld.global.v2.f32 {%f1,%f2}, [%rd42];
      st.shared.v2.f32 [%rd44], {%f1,%f2};
      add.u64 %rd42, %rd42, 8;
      add.u64 %rd44, %rd44, 8;
      ld.global.v2.f32 {%f1,%f2}, [%rd42];
      st.shared.v2.f32 [%rd44], {%f1,%f2};
      bra WLOAD_STEP;
  WLOAD_V4:
      ld.global.v4.f32 {%f1,%f2,%f3,%f4}, [%rd42];
      st.shared.v4.f32 [%rd44], {%f1,%f2,%f3,%f4};
  WLOAD_STEP:
      add.u32 %r72, %r72, %r73;
      bra WLOAD_VEC_LOOP;
  WLOAD_VEC_DONE:
      // Tail scalar copies for remaining elements
      add.u32 %r72, %r66, %r0;           // idx_tail = vec_end + tid
  WLOAD_TAIL_LOOP:
      setp.ge.u32 %p8, %r72, %r64;
      @%p8 bra WLOAD_DONE;
      add.u32 %r75, %r74, %r72;
      mul.wide.u32 %rd41, %r75, 4;
      add.u64 %rd42, %rd1, %rd41;
      mul.wide.u32 %rd43, %r72, 4;
      add.u64 %rd44, %rd40, %rd43;
      ld.global.f32 %f1, [%rd42];
      st.shared.f32 [%rd44], %f1;
      add.u32 %r72, %r72, %r1;           // idx_tail += blockDim.x
      bra WLOAD_TAIL_LOOP;
  WLOAD_DONE:
      // Broadcast bias to shared memory once per block
      setp.ne.u32 %p9, %r0, 0;
      @%p9 bra BIAS_DONE;
      // Compute bias address for oc and store to shared
      mul.wide.u32 %rd10, %r28, 4;
      add.u64 %rd11, %rd2, %rd10;
      ld.global.f32 %f6, [%rd11];
      mov.u64 %rd47, smemBias;
      st.shared.f32 [%rd47], %f6;
  BIAS_DONE:
      bar.sync 0;
    // Compute per-block ohow index for this thread
    mul.lo.u32 %r84, %r83, %r1;   // seg * blockDim.x
    add.u32 %r85, %r84, %r0;      // ohow index within (OH*OW)
    setp.ge.u32 %p0, %r85, %r68;
    @%p0 bra DONE;
    // Derive ow and oh from ohow index
    rem.u32 %r30, %r85, %r18;     // ow
    div.u32 %r5,  %r85, %r18;     // tmp = ohow / OW
    rem.u32 %r29, %r5,  %r17;     // oh
     // Load bias from shared into sum
     mov.u64 %rd47, smemBias;
     ld.shared.f32 %f0, [%rd47];
    // Cast constants to s32 for comparisons
    cvt.s32.u32 %s10, %r21;  // PADH
    cvt.s32.u32 %s11, %r22;  // PADW
    cvt.s32.u32 %s12, %r12;  // H
    cvt.s32.u32 %s13, %r13;  // W
    // c = 0
    // Precompute per-thread invariants
    mul.lo.u32 %r40, %r29, %r19;
    cvt.s32.u32 %s14, %r40;       // oh*STRH as s32
    mul.lo.u32 %r42, %r30, %r20;
    cvt.s32.u32 %s15, %r42;       // ow*STRW as s32
    // n*C
    mul.lo.u32 %r95, %r27, %r11;
    mov.u32 %r31, 0;
C_LOOP:
    setp.ge.u32 %p1, %r31, %r11;
    @%p1 bra C_DONE;
    // kh = 0
    mov.u32 %r32, 0;
KH_LOOP:
    setp.ge.u32 %p2, %r32, %r15;
    @%p2 bra C_NEXT;
    // sih = (oh*STRH + kh - PADH), with oh*STRH precomputed
    cvt.s32.u32 %s1, %r32;         // kh
    add.s32 %s2, %s14, %s1;
    sub.s32 %s2, %s2, %s10;        // s2 = sih
    // if (sih < 0 || sih >= H) goto KH_INC
    setp.lt.s32 %p3, %s2, 0;
    @%p3 bra KH_INC;
    setp.ge.s32 %p4, %s2, %s12;
    @%p4 bra KH_INC;
    // ih_u32 = (u32)sih
    cvt.u32.s32 %r41, %s2;
    // kw = 0
    // Precompute x row base: (((n*C + c)*H + ih) * W)
    add.u32 %r50, %r95, %r31;    // t0 = (n*C) + c
    mul.lo.u32 %r51, %r50, %r12; // *H
    add.u32 %r51, %r51, %r41;    // + ih
    mul.lo.u32 %r94, %r51, %r13; // *W
    // Precompute weight idx base: ((c*KH)+kh)*KW
    mul.lo.u32 %r90, %r31, %r15;
    add.u32 %r92, %r90, %r32;
    mul.lo.u32 %r92, %r92, %r16;
    mov.u32 %r33, 0;
  KW_LOOP:
      setp.ge.u32 %p5, %r33, %r16;
      @%p5 bra KH_INC;
      // Compute base indices
      cvt.s32.u32 %s4, %r33;        // kw_base
      add.s32 %s5, %s15, %s4;
      sub.s32 %s5, %s5, %s11;       // siw_base
      add.u32 %r90, %r92, %r33;     // weight idx base
      // Try vectorized-4 path when fully in-bounds and 16B aligned
      add.u32 %r70, %r33, 3;        // kw_base + 3
      setp.lt.u32 %p6, %r70, %r16;  // (kw_base+3) < KW
      setp.ge.s32 %p7, %s5, 0;      // siw_base >= 0
      and.pred %p6, %p6, %p7;
      add.s32 %s6, %s5, 3;
      setp.lt.s32 %p7, %s6, %s13;   // (siw_base+3) < W
      and.pred %p6, %p6, %p7;
      cvt.u32.s32 %r71, %s5;
      add.u32 %r52, %r94, %r71;     // x element index base
      and.b32 %r72, %r52, 3;        // alignment check: index % 4
      setp.eq.u32 %p7, %r72, 0;
      and.pred %p6, %p6, %p7;
      @!%p6 bra SCALAR_PATH;
      // Vectorized load of 4 input elements
      mul.wide.u32 %rd12, %r52, 4;
      add.u64 %rd13, %rd0, %rd12;
       ld.global.cg.v4.f32 {%f1,%f2,%f3,%f4}, [%rd13];
      // Sequential shared loads of 4 weights and FMAs
      mul.wide.u32 %rd45, %r90, 4;
      add.u64 %rd46, %rd40, %rd45;
      // Vectorized shared load of weights: prefer v4 when 16B aligned, else v2 when 8B aligned, else scalar
      and.b32 %r77, %r90, 3;
      setp.eq.u32 %p10, %r77, 0;
      @%p10 bra W_VEC4;
      and.b32 %r77, %r90, 1;
      setp.eq.u32 %p11, %r77, 0;
      @%p11 bra W_VEC2;
      // Scalar shared loads (unaligned case)
      ld.shared.f32 %f5, [%rd46];
      fma.rn.f32 %f0, %f1, %f5, %f0;
      add.u64 %rd46, %rd46, 4;
      ld.shared.f32 %f5, [%rd46];
      fma.rn.f32 %f0, %f2, %f5, %f0;
      add.u64 %rd46, %rd46, 4;
      ld.shared.f32 %f5, [%rd46];
      fma.rn.f32 %f0, %f3, %f5, %f0;
      add.u64 %rd46, %rd46, 4;
      ld.shared.f32 %f5, [%rd46];
      fma.rn.f32 %f0, %f4, %f5, %f0;
      bra W_VEC_DONE;
  W_VEC2:
      ld.shared.v2.f32 {%f5,%f6}, [%rd46];
      add.u64 %rd46, %rd46, 8;
      ld.shared.v2.f32 {%f7,%f8}, [%rd46];
      fma.rn.f32 %f0, %f1, %f5, %f0;
      fma.rn.f32 %f0, %f2, %f6, %f0;
      fma.rn.f32 %f0, %f3, %f7, %f0;
      fma.rn.f32 %f0, %f4, %f8, %f0;
      bra W_VEC_DONE;
  W_VEC4:
      ld.shared.v4.f32 {%f5,%f6,%f7,%f8}, [%rd46];
      fma.rn.f32 %f0, %f1, %f5, %f0;
      fma.rn.f32 %f0, %f2, %f6, %f0;
      fma.rn.f32 %f0, %f3, %f7, %f0;
      fma.rn.f32 %f0, %f4, %f8, %f0;
  W_VEC_DONE:
      add.u32 %r33, %r33, 4;
      bra KW_LOOP;
  SCALAR_PATH:
      // Scalar 4-lane unrolled path with per-lane bounds
      // Lane 0
      setp.lt.s32 %p6, %s5, 0;
      @%p6 bra LANE0_SKIP;
      setp.ge.s32 %p7, %s5, %s13;
      @%p7 bra LANE0_SKIP;
      cvt.u32.s32 %r43, %s5;
      add.u32 %r52, %r94, %r43;
      mul.wide.u32 %rd12, %r52, 4;
      add.u64 %rd13, %rd0, %rd12;
       ld.global.cg.f32 %f1, [%rd13];
      mul.wide.u32 %rd45, %r90, 4;
      add.u64 %rd46, %rd40, %rd45;
      ld.shared.f32 %f2, [%rd46];
      fma.rn.f32 %f0, %f1, %f2, %f0;
  LANE0_SKIP:
      // Lane 1
      add.u32 %r70, %r33, 1;
      setp.ge.u32 %p5, %r70, %r16;
      @%p5 bra LANE1_SKIP;
      add.s32 %s6, %s5, 1;
      setp.lt.s32 %p6, %s6, 0;
      @%p6 bra LANE1_SKIP;
      setp.ge.s32 %p7, %s6, %s13;
      @%p7 bra LANE1_SKIP;
      cvt.u32.s32 %r71, %s6;
      add.u32 %r52, %r94, %r71;
      mul.wide.u32 %rd12, %r52, 4;
      add.u64 %rd13, %rd0, %rd12;
       ld.global.cg.f32 %f1, [%rd13];
      add.u32 %r91, %r90, 1;
      mul.wide.u32 %rd45, %r91, 4;
      add.u64 %rd46, %rd40, %rd45;
      ld.shared.f32 %f2, [%rd46];
      fma.rn.f32 %f0, %f1, %f2, %f0;
  LANE1_SKIP:
      // Lane 2
      add.u32 %r72, %r33, 2;
      setp.ge.u32 %p5, %r72, %r16;
      @%p5 bra LANE2_SKIP;
      add.s32 %s7, %s5, 2;
      setp.lt.s32 %p6, %s7, 0;
      @%p6 bra LANE2_SKIP;
      setp.ge.s32 %p7, %s7, %s13;
      @%p7 bra LANE2_SKIP;
      cvt.u32.s32 %r73, %s7;
      add.u32 %r52, %r94, %r73;
      mul.wide.u32 %rd12, %r52, 4;
      add.u64 %rd13, %rd0, %rd12;
       ld.global.cg.f32 %f1, [%rd13];
      add.u32 %r93, %r90, 2;
      mul.wide.u32 %rd45, %r93, 4;
      add.u64 %rd46, %rd40, %rd45;
      ld.shared.f32 %f2, [%rd46];
      fma.rn.f32 %f0, %f1, %f2, %f0;
  LANE2_SKIP:
      // Lane 3
      add.u32 %r74, %r33, 3;
      setp.ge.u32 %p5, %r74, %r16;
      @%p5 bra LANE3_SKIP;
      add.s32 %s8, %s5, 3;
      setp.lt.s32 %p6, %s8, 0;
      @%p6 bra LANE3_SKIP;
      setp.ge.s32 %p7, %s8, %s13;
      @%p7 bra LANE3_SKIP;
      cvt.u32.s32 %r75, %s8;
      add.u32 %r52, %r94, %r75;
      mul.wide.u32 %rd12, %r52, 4;
      add.u64 %rd13, %rd0, %rd12;
       ld.global.cg.f32 %f1, [%rd13];
      add.u32 %r76, %r90, 3;
      mul.wide.u32 %rd45, %r76, 4;
      add.u64 %rd46, %rd40, %rd45;
      ld.shared.f32 %f2, [%rd46];
      fma.rn.f32 %f0, %f1, %f2, %f0;
  LANE3_SKIP:
      add.u32 %r33, %r33, 4;
      bra KW_LOOP;
KH_INC:
    add.u32 %r32, %r32, 1;
    bra KH_LOOP;
C_NEXT:
    add.u32 %r31, %r31, 1;
    bra C_LOOP;
C_DONE:
    // y index: (((n*OC + oc)*OH + oh)*OW + ow)
    mul.lo.u32 %r60, %r27, %r14; // n*OC
    add.u32 %r60, %r60, %r28;    // + oc
    mul.lo.u32 %r61, %r60, %r17; // *OH
    add.u32 %r61, %r61, %r29;    // + oh
    mul.lo.u32 %r62, %r61, %r18; // *OW
    add.u32 %r62, %r62, %r30;    // + ow
    mul.wide.u32 %rd20, %r62, 4;
    add.u64 %rd21, %rd3, %rd20;
     st.global.cg.f32 [%rd21], %f0;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        # Allocate output tensors with torch.empty only.
        # Launch PTX on the current PyTorch stream and return the output.
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        w = self.conv1.weight
        b = self.conv1.bias

        # Ensure parameters are on the same CUDA device and tensors are contiguous
        assert w.is_cuda and b.is_cuda and (w.device == x.device), "Call model.to(x.device) before forward to place weights/bias on the CUDA device"
        assert x.is_contiguous() and w.is_contiguous() and b.is_contiguous(), "x, w, b must be contiguous (NCHW for x, OIHW for w)"
        N, C, H, W = x.shape
        OC, _, KH, KW = w.shape

        # Ensure shared-memory staging buffer can hold C*KH*KW floats
        required_smem_floats = C * KH * KW
        assert required_smem_floats <= 1024, f"Increase smemW size to hold C*KH*KW={required_smem_floats} floats"
        stride = self.conv1.stride if isinstance(self.conv1.stride, tuple) else (self.conv1.stride, self.conv1.stride)
        padding = self.conv1.padding if isinstance(self.conv1.padding, tuple) else (self.conv1.padding, self.conv1.padding)
        SH, SW = int(stride[0]), int(stride[1])
        PH, PW = int(padding[0]), int(padding[1])

        OH = (H + 2 * PH - KH) // SH + 1
        OW = (W + 2 * PW - KW) // SW + 1

        y = torch.empty((N, OC, OH, OW), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        TPB = 256
        OHOW = OH * OW
        segments = (OHOW + TPB - 1) // TPB
        grid_x = N * OC * segments
        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(TPB, 1, 1),
            arguments=[
                x, w, b, y,
                u32(N), u32(C), u32(H), u32(W),
                u32(OC), u32(KH), u32(KW), u32(OH), u32(OW),
                u32(SH), u32(SW), u32(PH), u32(PW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

