import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pOC,
    .param .u32 pKH,
    .param .u32 pKW,
    .param .u32 pOH,
    .param .u32 pOW,
    .param .u32 pSTRH,
    .param .u32 pSTRW,
    .param .u32 pPADH,
    .param .u32 pPADW
)
{
    .reg .pred %p<12>;
    .reg .u32 %r<96>;
    .reg .u64 %rd<48>;
    .reg .s32 %s<16>;
    .reg .f32 %f<12>;
    .shared .align 16 .b8 smemW[4096];
    .shared .align 4 .b8 smemBias[4];
    // Load pointers
    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [b_ptr];
    ld.param.u64 %rd3, [y_ptr];
    // Load scalars
    ld.param.u32 %r10, [pN];
    ld.param.u32 %r11, [pC];
    ld.param.u32 %r12, [pH];
    ld.param.u32 %r13, [pW];
    ld.param.u32 %r14, [pOC];
    ld.param.u32 %r15, [pKH];
    ld.param.u32 %r16, [pKW];
    ld.param.u32 %r17, [pOH];
