_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        # Allocate output tensors with torch.empty only.
        # Launch PTX on the current PyTorch stream and return the output.
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        w = self.conv1.weight
        b = self.conv1.bias

        # Ensure parameters are on the same CUDA device and tensors are contiguous
        assert w.is_cuda and b.is_cuda and (w.device == x.device), "Call model.to(x.device) before forward to place weights/bias on the CUDA device"
        assert x.is_contiguous() and w.is_contiguous() and b.is_contiguous(), "x, w, b must be contiguous (NCHW for x, OIHW for w)"
        N, C, H, W = x.shape
        OC, _, KH, KW = w.shape

        # Ensure shared-memory staging buffer can hold C*KH*KW floats
        required_smem_floats = C * KH * KW
        assert required_smem_floats <= 1024, f"Increase smemW size to hold C*KH*KW={required_smem_floats} floats"
        stride = self.conv1.stride if isinstance(self.conv1.stride, tuple) else (self.conv1.stride, self.conv1.stride)
        padding = self.conv1.padding if isinstance(self.conv1.padding, tuple) else (self.conv1.padding, self.conv1.padding)
        SH, SW = int(stride[0]), int(stride[1])
        PH, PW = int(padding[0]), int(padding[1])

        OH = (H + 2 * PH - KH) // SH + 1
        OW = (W + 2 * PW - KW) // SW + 1

        y = torch.empty((N, OC, OH, OW), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        TPB = 256
        OHOW = OH * OW
        segments = (OHOW + TPB - 1) // TPB
        grid_x = N * OC * segments
        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(TPB, 1, 1),
            arguments=[
                x, w, b, y,
                u32(N), u32(C), u32(H), u32(W),
                u32(OC), u32(KH), u32(KW), u32(OH), u32(OW),
                u32(SH), u32(SW), u32(PH), u32(PW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
